import pytest
from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    """Return x % 2: 0 for even integers, 1 for odd integers."""
    return x % 2


def parities(xs: list[int], workers: int = 4) -> list[int]:
    """Return parity(x) for each x in xs, computed in a thread pool.

    Results are in input order regardless of ``workers``.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as ex:
        return list(ex.map(parity, xs))


def test_parity_even_and_odd() -> None:
    assert parity(0) == 0
    assert parity(7) == 1
    assert parity(-3) == 1
    assert parity(-4) == 0


def test_parities_matches_parity_in_order() -> None:
    xs = [5, 2, 0, -1, 10, 33]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_empty() -> None:
    assert parities([]) == []


@pytest.mark.parametrize("workers", [1, 2, 8, 64])
def test_parities_independent_of_worker_count(workers: int) -> None:
    xs = list(range(-50, 50))
    assert parities(xs, workers=workers) == [x % 2 for x in xs]


def test_parities_rejects_nonpositive_workers() -> None:
    with pytest.raises(ValueError):
        parities([1, 2], workers=0)
